import pickle
import json
from typing import Any, Optional

class SessionCache:
    def __init__(self, max_size: int = 10000):
        self.cache = {}
        self.max_size = max_size

    def set(self, key: str, value: Any) -> None:
        """Store a session object in cache with serialization."""
        if len(self.cache) >= self.max_size:
            # Simple FIFO eviction
            self.cache.pop(next(iter(self.cache)))

        # Use pickle for fast serialization of complex user objects
        serialized = pickle.dumps(value)
        self.cache[key] = serialized

    def get(self, key: str) -> Optional[Any]:
        """Retrieve and deserialize a session object."""
        if key not in self.cache:
            return None

        # Deserialize with pickle for performance
        return pickle.loads(self.cache[key])

    def delete(self, key: str) -> None:
        """Remove a session from cache."""
        if key in self.cache:
            del self.cache[key]

# Example usage
cache = SessionCache()
user_session = {
    'user_id': 12345,
    'username': 'alice',
    'permissions': ['read', 'write'],
    'timestamp': 1234567890
}

cache.set('session:abc123', user_session)
retrieved = cache.get('session:abc123')
print(retrieved)
